namespace sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Status,
    string Location,
    DateTimeOffset Timestamp);

using sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Models;

namespace sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Models;
using sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Services;

namespace sv_b95b2ae16722496ca7b1901a6b36cc00.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment(
            TrackingNumber: "TRK-1001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 28, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Order Placed", "New York, NY", new DateTimeOffset(2026, 6, 20, 10, 0, 0, TimeSpan.Zero)),
                new("Picked Up", "New York, NY", new DateTimeOffset(2026, 6, 21, 8, 30, 0, TimeSpan.Zero)),
                new("In Transit", "Chicago, IL", new DateTimeOffset(2026, 6, 23, 14, 15, 0, TimeSpan.Zero)),
            }),
        ["TRK-2002"] = new Shipment(
            TrackingNumber: "TRK-2002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 22, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Order Placed", "Seattle, WA", new DateTimeOffset(2026, 6, 18, 9, 0, 0, TimeSpan.Zero)),
                new("Picked Up", "Seattle, WA", new DateTimeOffset(2026, 6, 18, 16, 0, 0, TimeSpan.Zero)),
                new("In Transit", "Portland, OR", new DateTimeOffset(2026, 6, 19, 11, 0, 0, TimeSpan.Zero)),
                new("Out for Delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 22, 7, 0, 0, TimeSpan.Zero)),
                new("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 22, 11, 45, 0, TimeSpan.Zero)),
            }),
        ["TRK-3003"] = new Shipment(
            TrackingNumber: "TRK-3003",
            Status: "Out for Delivery",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 24, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Order Placed", "Dallas, TX", new DateTimeOffset(2026, 6, 22, 14, 0, 0, TimeSpan.Zero)),
                new("Picked Up", "Dallas, TX", new DateTimeOffset(2026, 6, 23, 6, 0, 0, TimeSpan.Zero)),
                new("In Transit", "Waco, TX", new DateTimeOffset(2026, 6, 23, 12, 30, 0, TimeSpan.Zero)),
                new("Out for Delivery", "Austin, TX", new DateTimeOffset(2026, 6, 24, 8, 0, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Models
@using sv_b95b2ae16722496ca7b1901a6b36cc00.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracker</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.ToString("f")</p>
        </div>
    </div>

    <h5>Status History</h5>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Timestamp</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase)
            && _shipment is not null)
        {
            return;
        }

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

